solution.js:
let tickets = 0;
const preis = 12;
const knopf = document.getElementById("plus");
knopf.addEventListener("click", function () {
  tickets = tickets + 1;
  document.getElementById("anzahl").textContent = tickets;
  document.getElementById("summe").textContent = "Summe: " + tickets * preis + " €";
});
